<?php
namespace App\Services;use App\Models\Order;use App\Models\ReturnRequest;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use Illuminate\Validation\ValidationException;
class ReturnService{public function request(Order $order,array $data,?int $userId):ReturnRequest{if(!in_array($order->status,['delivered','shipped']))throw ValidationException::withMessages(['order'=>'This order is not eligible for return.']);return DB::transaction(function()use($order,$data,$userId){$r=ReturnRequest::create(['uuid'=>(string)Str::uuid(),'number'=>'RET-'.now()->format('ymdHis'),'order_id'=>$order->id,'user_id'=>$userId,'type'=>$data['type'],'reason'=>$data['reason'],'details'=>$data['details']??null,'requested_amount'=>$data['requested_amount']??0]);foreach($data['items'] as $i)$r->items()->create($i);app(OrderLifecycleService::class)->transition($order,'return_requested',$userId,'Customer return requested.');return $r->fresh('items');});}public function review(ReturnRequest $return,string $decision,float $amount,int $userId):void{abort_unless($return->status==='requested',422);abort_unless(in_array($decision,['approved','rejected']),422);$return->update(['status'=>$decision,'approved_amount'=>$decision==='approved'?$amount:0,'reviewed_by'=>$userId,'reviewed_at'=>now()]);}}
